-- Demo problems (parents are listed before their parts).
insert into public.problems (id, assignment_id, parent_problem_id, label, slug, display_order, title, statement_markdown,
                             statement_source, extraction_status, created_by)
select v.id::uuid, a.id, v.parent_problem_id::uuid, v.label, v.slug, v.display_order::int, v.title, v.statement_markdown,
       case when v.statement_markdown is null then 'none' else 'manual' end::public.statement_source,
       case when v.statement_markdown is null then 'none' else 'reviewed' end::public.extraction_status,
       null
  from (values
  ('35e67959-88d3-418a-b663-070f55f6ee18', 'c71e3643-6170-4e42-8aec-08e1bcae4380', null, '1', 'p1', 1, null, 'Let $G$ be a group in which $g^2 = e$ for every $g \in G$. Prove that $G$ is abelian.'),
  ('32e674a0-87d3-4ff7-b763-08a258f6f2d1', 'c71e3643-6170-4e42-8aec-08e1bcae4380', null, '2', 'p2', 2, null, 'Show that the intersection of two subgroups of a group $G$ is a subgroup. Give an example where the union of two subgroups is **not** a subgroup.'),
  ('33e67633-86d3-4e64-b863-0a3557f6f13e', 'c71e3643-6170-4e42-8aec-08e1bcae4380', null, '3', 'p3', 3, null, 'Let $G$ be a finite group. Prove that every subgroup of index $2$ is normal.'),
  ('38e67e12-85d3-4cd1-b162-ff305af6f5f7', 'c71e3643-6170-4e42-8aec-08e1bcae4380', null, '4', 'p4', 4, null, null),
  ('c6ede505-ea0f-4e90-96ed-4eef09cd5a62', 'c71e3643-6170-4e42-8aec-08e1bcae4380', '38e67e12-85d3-4cd1-b162-ff305af6f5f7', 'a', 'p4a', 1, null, 'Determine every subgroup of $\mathbb{Z}/12\mathbb{Z}$.'),
  ('c3ede04c-ed0f-4349-97ed-508208cd58cf', 'c71e3643-6170-4e42-8aec-08e1bcae4380', '38e67e12-85d3-4cd1-b162-ff305af6f5f7', 'b', 'p4b', 2, null, 'Show that for each divisor $d$ of $n$, the cyclic group $\mathbb{Z}/n\mathbb{Z}$ has exactly one subgroup of order $d$.'),
  ('39e67fa5-84d3-4b3e-b263-00c359f6f464', 'c71e3643-6170-4e42-8aec-08e1bcae4380', null, '5', 'p5', 5, null, 'Prove that a finite group of even order contains an element of order $2$.'),
  ('0fbd2cf3-6e6c-46b8-b162-50c9bff5cc2e', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', null, '1', 'p1', 1, null, 'Prove that the symmetric group $S_n$ is generated by the transpositions $(1\,2), (1\,3), \dots, (1\,n)$.'),
  ('10bd2e86-716c-4b71-ae62-4c10bef5ca9b', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', null, '2', 'p2', 2, null, 'List the conjugacy classes of $S_4$ and verify the class equation
$$|G| = |Z(G)| + \sum_i [G : C_G(g_i)].$$'),
  ('11bd3019-706c-49de-af62-4da3bdf5c908', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', null, '3', 'p3', 3, null, 'Let $H \le G$ with $[G:H] = n < \infty$. Show that $G$ has a normal subgroup $N \subseteq H$ whose index divides $n!$.'),
  ('12bd31ac-736c-4e97-b462-5582c4f5d40d', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', null, '4', 'p4', 4, 'Simplicity of $A_5$', 'Prove that the alternating group $A_5$ is simple.'),
  ('13bd333f-726c-4d04-b562-5715c3f5d27a', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', null, '5', 'p5', 5, null, 'Classify all groups of order $p^2$, where $p$ is prime.'),
  ('14bd34d2-756c-41bd-b262-525cc2f5d0e7', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', null, '6', 'p6', 6, null, null),
  ('6315acb1-a049-426c-8145-4fc7eb8ecf7a', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', '14bd34d2-756c-41bd-b262-525cc2f5d0e7', 'a', 'p6a', 1, null, 'Prove that the center of a nontrivial finite $p$-group is nontrivial.'),
  ('6015a7f8-a349-4725-8245-515aea8ecde7', 'c61e34b0-6270-4fd5-89ec-074ebdae4513', '14bd34d2-756c-41bd-b262-525cc2f5d0e7', 'b', 'p6b', 2, null, 'Deduce that every group of order $p^n$ has a normal subgroup of order $p^k$ for each $0 \le k \le n$.'),
  ('e4c977e5-853b-42da-bf26-c1276edf137c', 'c91e3969-5f70-4b1c-88ec-05bbbeae46a6', null, '1', 'p1', 1, null, 'Show that there is no simple group of order $56$.'),
  ('e1c9732c-843b-4147-8026-c2ba71df1835', 'c91e3969-5f70-4b1c-88ec-05bbbeae46a6', null, '2', 'p2', 2, null, 'Prove that every group of order $15$ is cyclic.'),
  ('e2c974bf-833b-4fb4-8126-c44d70df16a2', 'c91e3969-5f70-4b1c-88ec-05bbbeae46a6', null, '3', 'p3', 3, null, 'Let $P$ be a Sylow $p$-subgroup of a finite group $G$, and let $N = N_G(P)$. Prove that $N_G(N) = N$.'),
  ('dfc97006-823b-4e21-ba26-b9486bdf0ec3', 'c91e3969-5f70-4b1c-88ec-05bbbeae46a6', null, '4', 'p4', 4, 'Groups of order 12', 'Classify the groups of order $12$ up to isomorphism.'),
  ('e0c97199-813b-4c8e-bb26-badb6adf0d30', 'c91e3969-5f70-4b1c-88ec-05bbbeae46a6', null, '5', 'p5', 5, null, 'Let $p$ and $q$ be distinct primes. Prove that no group of order $p^2 q$ is simple.'),
  ('ddc96ce0-803b-4afb-bc26-bc6e6ddf11e9', 'c91e3969-5f70-4b1c-88ec-05bbbeae46a6', null, '6', 'p6', 6, null, null),
  ('c0b9a268-ec82-474f-b0b3-0afe32e536d5', 'c81e37d6-6070-4caf-87ec-0428bfae4839', null, '1', 'p1', 1, null, 'Let $U, W$ be subspaces of a finite-dimensional vector space $V$. Prove that
$$\dim(U + W) = \dim U + \dim W - \dim(U \cap W).$$'),
  ('c3b9a721-ed82-48e2-afb3-096b2fe5321c', 'c81e37d6-6070-4caf-87ec-0428bfae4839', null, '2', 'p2', 2, null, 'Let $T : V \to V$ be linear with $T^2 = T$. Show that $V = \ker T \oplus \operatorname{im} T$.'),
  ('c2b9a58e-ee82-4a75-aeb3-07d830e533af', 'c81e37d6-6070-4caf-87ec-0428bfae4839', null, '3', 'p3', 3, null, null),
  ('8f73dbc7-a4af-4c3a-b577-ac2d9e1a9ad0', 'c81e37d6-6070-4caf-87ec-0428bfae4839', 'c2b9a58e-ee82-4a75-aeb3-07d830e533af', 'a', 'p3a', 1, null, 'For a subspace $U \subseteq V$, construct the quotient $V/U$ and show it is a vector space.'),
  ('9073dd5a-a3af-4aa7-b277-a774a11a9f89', 'c81e37d6-6070-4caf-87ec-0428bfae4839', 'c2b9a58e-ee82-4a75-aeb3-07d830e533af', 'b', 'p3b', 2, null, 'If $\dim V < \infty$, prove $\dim V/U = \dim V - \dim U$.'),
  ('9173deed-a2af-4914-b377-a907a01a9df6', 'c81e37d6-6070-4caf-87ec-0428bfae4839', 'c2b9a58e-ee82-4a75-aeb3-07d830e533af', 'c', 'p3c', 3, null, 'Prove the *universal property*: every linear map $T: V \to W$ with $U \subseteq \ker T$ factors uniquely through $V \to V/U$.'),
  ('c5b9aa47-e782-4f70-b5b3-12dd2de52ef6', 'c81e37d6-6070-4caf-87ec-0428bfae4839', null, '4', 'p4', 4, null, 'Show that $V \cong V^{**}$ naturally when $\dim V < \infty$, and that $V \to V^{**}$ is not surjective when $V$ has a countably infinite basis.'),
  ('c4b9a8b4-e882-4103-b4b3-114a2ee53089', 'c81e37d6-6070-4caf-87ec-0428bfae4839', null, '5', 'p5', 5, null, 'Let $\mathbb{F}$ be a field with $q$ elements. Count the number of ordered bases of $\mathbb{F}^n$, and deduce $|GL_n(\mathbb{F})|$.'),
  ('b56109f2-ab10-4dcd-9476-ad34f9d7c6a7', 'cb1e3c8f-5d70-47f6-8eec-0f2dc0ae49cc', null, '1', 'p1', 1, null, 'Prove that eigenvectors of a linear operator corresponding to distinct eigenvalues are linearly independent.'),
  ('b461085f-a810-4914-9776-b1edfad7c83a', 'cb1e3c8f-5d70-47f6-8eec-0f2dc0ae49cc', null, '2', 'p2', 2, null, 'Let $V$ be a finite-dimensional complex vector space and $T \in \mathcal{L}(V)$. Prove that $T$ has an upper-triangular matrix with respect to some basis.'),
  ('b36106cc-a910-4aa7-9676-b05afbd7c9cd', 'cb1e3c8f-5d70-47f6-8eec-0f2dc0ae49cc', null, '3', 'p3', 3, null, 'Show that a family of pairwise commuting diagonalizable operators on a finite-dimensional space is simultaneously diagonalizable.'),
  ('b2610539-a610-45ee-9176-a87bf4d7bec8', 'cb1e3c8f-5d70-47f6-8eec-0f2dc0ae49cc', null, '4', 'p4', 4, null, 'Find the Jordan canonical form of
$$A = \begin{pmatrix} 2 & 1 & 0 \\ 0 & 2 & 0 \\ 0 & 1 & 3 \end{pmatrix}.$$'),
  ('b16103a6-a710-4781-9076-a6e8f5d7c05b', 'cb1e3c8f-5d70-47f6-8eec-0f2dc0ae49cc', null, '5', 'p5', 5, 'Cayley–Hamilton', 'Prove the Cayley–Hamilton theorem: every square matrix over a field satisfies its own characteristic polynomial.'),
  ('b0610213-a410-42c8-9376-aba1f6d7c1ee', 'cb1e3c8f-5d70-47f6-8eec-0f2dc0ae49cc', null, '6', 'p6', 6, null, 'Let $N$ be nilpotent on $V$ with $\dim V = n$. Show that the number of Jordan blocks of size $\ge k$ equals $\dim \ker N^k - \dim \ker N^{k-1}$.'),
  ('78c76c48-b8d5-4ac7-9c1c-d6c2a06b8631', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '1', 'p1', 1, null, 'Prove the Cauchy–Schwarz inequality $|\langle u, v\rangle| \le \|u\|\,\|v\|$ in any inner product space, with equality if and only if $u$ and $v$ are linearly dependent.'),
  ('7bc77101-b9d5-4c5a-9b1c-d52f9d6b8178', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '2', 'p2', 2, null, 'Apply Gram–Schmidt to $1, x, x^2$ in $\mathcal{P}_2(\mathbb{R})$ with $\langle f, g \rangle = \int_{-1}^{1} f(x) g(x)\,dx$.'),
  ('7ac76f6e-bad5-4ded-9a1c-d39c9e6b830b', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '3', 'p3', 3, null, 'State and prove the spectral theorem for self-adjoint operators on a finite-dimensional real inner product space.'),
  ('7dc77427-b3d5-42e8-991c-d209a36b8aea', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '4', 'p4', 4, null, 'Show that every invertible operator $T$ on a finite-dimensional inner product space can be written $T = SP$ with $S$ an isometry and $P$ positive definite.'),
  ('7cc77294-b4d5-447b-981c-d076a46b8c7d', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '5', 'p5', 5, null, 'Let $A$ be an $n \times n$ real matrix with $A^{\mathsf T} A = A A^{\mathsf T}$. Prove that $A$ is orthogonally similar to a block-diagonal matrix with blocks of size at most $2$.'),
  ('7fc7774d-b5d5-460e-971c-cee3a16b87c4', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '6', 'p6', 6, null, 'Let $T$ be normal. Prove that $\|T\| = \max \{ |\lambda| : \lambda \text{ an eigenvalue of } T\}$.'),
  ('7ec775ba-b6d5-47a1-961c-cd50a26b8957', 'ca1e3afc-5e70-4989-8dec-0d9ac1ae4b5f', null, '7', 'p7', 7, null, null),
  ('f7576b0d-69db-4fe6-87d1-64bfa3a52a28', 'cd1e3fb5-5b70-44d0-8cec-0c07c2ae4cf2', null, '1', 'p1', 1, null, 'Construct the tensor product $V \otimes W$ by a universal property and show $\dim(V \otimes W) = \dim V \cdot \dim W$.'),
  ('f4576654-68db-4e53-88d1-6652a6a52ee1', 'cd1e3fb5-5b70-44d0-8cec-0c07c2ae4cf2', null, '2', 'p2', 2, null, 'Show that $V^* \otimes W \cong \operatorname{Hom}(V, W)$ for finite-dimensional $V$, and identify the trace with the contraction map.'),
  ('f55767e7-67db-4cc0-89d1-67e5a5a52d4e', 'cd1e3fb5-5b70-44d0-8cec-0c07c2ae4cf2', null, '3', 'p3', 3, null, null),
