  ('cb3d7b11-2330-4fcc-9186-21f70939c71a', 'cd1e3fb5-5b70-44d0-8cec-0c07c2ae4cf2', 'f55767e7-67db-4cc0-89d1-67e5a5a52d4e', 'b', 'p3b', 2, null, 'Use the top exterior power to give a basis-free definition of the determinant and prove $\det(ST) = \det S \det T$.'),
  ('f257632e-6edb-47c5-82d1-5ce0a8a53207', 'cd1e3fb5-5b70-44d0-8cec-0c07c2ae4cf2', null, '4', 'p4', 4, null, 'Prove that $v_1, \dots, v_k$ are linearly independent if and only if $v_1 \wedge \cdots \wedge v_k \ne 0$.'),
  ('f35764c1-6ddb-4632-83d1-5e73a7a53074', 'cd1e3fb5-5b70-44d0-8cec-0c07c2ae4cf2', null, '5', 'p5', 5, null, 'Compute the dimension of $\operatorname{Sym}^k V$ for $\dim V = n$.'),
  ('2ce26b37-7759-4790-9f19-0d318a1f9b92', 'cc1e3e22-5c70-4663-8bec-0a74c3ae4e85', null, '1', 'p1', 1, null, 'Show that a finite integral domain is a field.'),
  ('2de26cca-7a59-4c49-9c19-0878891f99ff', 'cc1e3e22-5c70-4663-8bec-0a74c3ae4e85', null, '2', 'p2', 2, null, 'Prove that $\mathbb{Z}[i]$ is a Euclidean domain, and use this to determine which primes are sums of two squares.'),
  ('2ee26e5d-7959-4ab6-9d19-0a0b881f986c', 'cc1e3e22-5c70-4663-8bec-0a74c3ae4e85', null, '3', 'p3', 3, null, 'Show that $\mathbb{Z}[\sqrt{-5}]$ is not a unique factorization domain.'),
  ('27e26358-7c59-4f6f-a219-11ea871f96d9', 'cc1e3e22-5c70-4663-8bec-0a74c3ae4e85', null, '4', 'p4', 4, null, 'Let $R$ be a PID. Prove that every nonzero prime ideal of $R$ is maximal.'),
  ('28e264eb-7b59-4ddc-a319-137d861f9546', 'cc1e3e22-5c70-4663-8bec-0a74c3ae4e85', null, '5', 'p5', 5, null, 'Prove the Chinese remainder theorem for pairwise comaximal ideals of a commutative ring.'),
  ('29e2667e-7e59-4295-a019-0ec4851f93b3', 'cc1e3e22-5c70-4663-8bec-0a74c3ae4e85', null, '6', 'p6', 6, null, null),
