  ('7111f2b1-d98d-4412-8d5e-e6cb54ca841c', 'f9f7ad8c-5ac1-4781-befe-039e02c7ffd3', null, '1', 'p1', 1, null, 'How many ways are there to arrange the letters of the word *STATISTICS*?'),
  ('6e11edf8-d88d-427f-8e5e-e85e57ca88d5', 'f9f7ad8c-5ac1-4781-befe-039e02c7ffd3', null, '2', 'p2', 2, null, 'A committee of $5$ is chosen from $8$ women and $6$ men. What is the probability it has at least $2$ men?'),
  ('6f11ef8b-d78d-40ec-8f5e-e9f156ca8742', 'f9f7ad8c-5ac1-4781-befe-039e02c7ffd3', null, '3', 'p3', 3, null, 'Give a story proof of $\displaystyle\sum_{k=0}^{n} \binom{n}{k}^2 = \binom{2n}{n}$.'),
  ('7411f76a-d68d-4f59-905e-eb8451ca7f63', 'f9f7ad8c-5ac1-4781-befe-039e02c7ffd3', null, '4', 'p4', 4, null, 'In a group of $n$ people, find the probability that at least two share a birthday, and the smallest $n$ for which it exceeds $1/2$.'),
  ('7511f8fd-d58d-4dc6-915e-ed1750ca7dd0', 'f9f7ad8c-5ac1-4781-befe-039e02c7ffd3', null, '5', 'p5', 5, null, 'Show that $P(A \cup B \cup C)$ can be expanded by inclusion–exclusion, and apply it to count derangements of $4$ letters.'),
