  ('cb8fc5d7-df0c-47f0-b3c4-c6b54818f25e', 'faf7af1f-59c1-45ee-bffe-053101c7fe40', null, '2', 'p2', 2, null, 'Three doors hide one prize. You pick a door; the host, who knows where the prize is, opens another door with no prize. Should you switch? Justify with conditioning.'),
  ('ca8fc444-e00c-4983-b2c4-c5224918f3f1', 'faf7af1f-59c1-45ee-bffe-053101c7fe40', null, '3', 'p3', 3, null, null),
  ('2b71fc41-8e9d-429c-84f6-2d039c00589e', 'faf7af1f-59c1-45ee-bffe-053101c7fe40', 'ca8fc444-e00c-4983-b2c4-c5224918f3f1', 'a', 'p3a', 1, null, 'Show that independence of $A$ and $B$ implies independence of $A^c$ and $B^c$.'),
  ('2871f788-919d-4755-85f6-2e969b00570b', 'faf7af1f-59c1-45ee-bffe-053101c7fe40', 'ca8fc444-e00c-4983-b2c4-c5224918f3f1', 'b', 'p3b', 2, null, 'Give three events that are pairwise independent but not independent.'),
  ('c98fc2b1-e50c-4162-adc4-bd434a18f584', 'faf7af1f-59c1-45ee-bffe-053101c7fe40', null, '4', 'p4', 4, null, 'Gambler’s ruin: starting with $i$ dollars, betting $1$ each round with win probability $p$, find the probability of reaching $N$ before $0$.'),
  ('c88fc11e-e60c-42f5-acc4-bbb04b18f717', 'faf7af1f-59c1-45ee-bffe-053101c7fe40', null, '5', 'p5', 5, null, null),
  ('b92c7dbd-8590-464e-87a6-c76bbb70b15c', 'fbf7b0b2-58c1-445b-bcfe-007804c802f9', null, '1', 'p1', 1, null, 'Let $X \sim \operatorname{Bin}(n, p)$. Derive $E[X]$ using indicator random variables.'),
  ('b62c7904-8490-44bb-88a6-c8febe70b615', 'fbf7b0b2-58c1-445b-bcfe-007804c802f9', null, '2', 'p2', 2, null, 'Find the expected number of distinct values seen when rolling a fair die $n$ times.'),
  ('b72c7a97-8390-4328-89a6-ca91bd70b482', 'fbf7b0b2-58c1-445b-bcfe-007804c802f9', null, '3', 'p3', 3, null, 'Show that the Poisson distribution is the limit of $\operatorname{Bin}(n, \lambda/n)$ as $n \to \infty$.'),
  ('b42c75de-8a90-4e2d-8aa6-cc24b870aca3', 'fbf7b0b2-58c1-445b-bcfe-007804c802f9', null, '4', 'p4', 4, null, 'Coupon collector: find the expected number of draws needed to collect all $n$ coupon types.'),
  ('57f3647f-acb3-4468-a4b8-0615e34f1706', 'fcf7b245-57c1-42c8-bdfe-020b03c80166', null, '1', 'p1', 1, null, 'Let $U \sim \operatorname{Unif}(0,1)$. Find the distribution of $-\log U$.'),
  ('58f36612-afb3-4921-a1b8-015ce24f1573', 'fcf7b245-57c1-42c8-bdfe-020b03c80166', null, '2', 'p2', 2, null, 'Prove the memoryless property of the exponential distribution and show it is the only continuous distribution with this property.'),
  ('59f367a5-aeb3-478e-a2b8-02efe14f13e0', 'fcf7b245-57c1-42c8-bdfe-020b03c80166', null, '3', 'p3', 3, null, 'Let $Z \sim \mathcal{N}(0,1)$. Compute $E[Z^4]$ and $E[|Z|]$.'),
  ('52f35ca0-b1b3-4c47-9fb7-fe36e84f1ee5', 'fcf7b245-57c1-42c8-bdfe-020b03c80166', null, '4', 'p4', 4, null, null),
  ('53f35e33-b0b3-4ab4-a0b7-ffc9e74f1d52', 'fcf7b245-57c1-42c8-bdfe-020b03c80166', null, '5', 'p5', 5, null, 'Break a stick of length $1$ at two uniformly random points. Find the probability that the three pieces form a triangle.'),
  ('ef5be5f8-a1b5-4a6f-ba5f-7d16c78cd3dd', 'f5f7a740-5ec1-4dcd-82fe-09ea06c8061f', null, '1', 'p1', 1, null, 'Let $X, Y$ be i.i.d. $\operatorname{Expo}(\lambda)$. Find the distribution of $\min(X, Y)$ and of $X - Y$.'),
  ('f25beab1-a2b5-4c02-b95f-7b83c48ccf24', 'f5f7a740-5ec1-4dcd-82fe-09ea06c8061f', null, '2', 'p2', 2, null, 'Compute $\operatorname{Cov}(X, Y)$ for $(X, Y)$ uniform on the unit disk, and show $X, Y$ are uncorrelated but dependent.'),
  ('f15be91e-a3b5-4d95-b85f-79f0c58cd0b7', 'f5f7a740-5ec1-4dcd-82fe-09ea06c8061f', null, '3', 'p3', 3, null, 'Use the change-of-variables formula to derive the Box–Muller transform.'),
  ('f45bedd7-9cb5-4290-bf5f-84f5c28ccbfe', 'f5f7a740-5ec1-4dcd-82fe-09ea06c8061f', null, '4', 'p4', 4, null, null),
  ('6a214daa-771f-4a71-a42c-2b009d9a38e7', 'f6f7a8d3-5dc1-4c3a-83fe-0b7d05c8048c', null, '1', 'p1', 1, null, 'State and apply Markov’s and Chebyshev’s inequalities to bound $P(|X - \mu| > 3\sigma)$.'),
  ('69214c17-741f-45b8-a72c-2fb99e9a3a7a', 'f6f7a8d3-5dc1-4c3a-83fe-0b7d05c8048c', null, '2', 'p2', 2, null, 'Prove the weak law of large numbers for i.i.d. random variables with finite variance.'),
  ('68214a84-751f-474b-a62c-2e269f9a3c0d', 'f6f7a8d3-5dc1-4c3a-83fe-0b7d05c8048c', null, '3', 'p3', 3, null, 'Use the central limit theorem to approximate the probability that $100$ fair dice sum to more than $370$.'),
  ('672148f1-7a1f-4f2a-a92c-32df989a3108', 'f6f7a8d3-5dc1-4c3a-83fe-0b7d05c8048c', null, '4', 'p4', 4, null, 'Let $X_1, X_2, \dots$ be i.i.d. $\operatorname{Unif}(0,1)$ and $N = \min\{n : X_1 + \dots + X_n > 1\}$. Show $E[N] = e$.'),
  ('b91565c8-f309-42ff-9b89-8e0e151c7c6d', '8ba9174c-90e1-4a2f-aed6-63eaf62e6b75', null, '1', 'p1', 1, null, 'Prove by induction that every binary string of length $n$ can be encoded as a natural number less than $2^{n+1}$, and give an explicit prefix-free encoding of pairs of strings.'),
  ('bc156a81-f409-4492-9a89-8c7b121c77b4', '8ba9174c-90e1-4a2f-aed6-63eaf62e6b75', null, '2', 'p2', 2, null, 'Show that the set of finite binary strings is countable, but the set of infinite binary sequences is not.'),
  ('bb1568ee-f509-4625-9989-8ae8131c7947', '8ba9174c-90e1-4a2f-aed6-63eaf62e6b75', null, '3', 'p3', 3, null, null),
