  ('28e73f3a-1a47-4a37-b0ea-6064487839f1', '8ba9174c-90e1-4a2f-aed6-63eaf62e6b75', 'bb1568ee-f509-4625-9989-8ae8131c7947', 'b', 'p3b', 2, null, 'Give a `NAND` circuit for the majority function on three bits with as few gates as you can.'),
  ('be156da7-ee09-4b20-a089-95ed101c748e', '8ba9174c-90e1-4a2f-aed6-63eaf62e6b75', null, '4', 'p4', 4, null, 'Prove that every function $f : \{0,1\}^n \to \{0,1\}$ can be computed by a circuit of size $O(n 2^n)$.'),
  ('9706a1c4-9797-4e27-8654-e5523f809285', '8ca918df-8fe1-489c-afd6-657df52e69e2', null, '1', 'p1', 1, null, 'Design a deterministic finite automaton accepting binary strings whose value is divisible by $3$.'),
  ('9a06a67d-9897-4fba-8554-e3bf3c808dcc', '8ca918df-8fe1-489c-afd6-657df52e69e2', null, '2', 'p2', 2, null, 'Use the pumping lemma to show that $\{0^n 1^n : n \ge 0\}$ is not regular.'),
  ('9906a4ea-9997-414d-8454-e22c3d808f5f', '8ca918df-8fe1-489c-afd6-657df52e69e2', null, '3', 'p3', 3, null, null),
