  ('b8c6e94e-dd3f-4a2f-b32c-6700aae86099', '8ca918df-8fe1-489c-afd6-657df52e69e2', '9906a4ea-9997-414d-8454-e22c3d808f5f', 'b', 'p3b', 2, null, 'Show that if $L$ is regular then so is $\{x : xy \in L \text{ for some } y \text{ with } |y| = |x|\}$.'),
  ('b9c6eae1-dc3f-489c-b42c-6893a9e85f06', '8ca918df-8fe1-489c-afd6-657df52e69e2', '9906a4ea-9997-414d-8454-e22c3d808f5f', 'c', 'p3c', 3, null, null),
